arguments.new_string:
def _env_float(
    name: str,
    default: float,
    minimum: float | None = None,
    maximum: float | None = None,
) -> float:
    raw = os.getenv(name)
    if raw is None or not raw.strip():
        return default
    try:
        val = float(raw)
    except ValueError:
        logger.warning("Invalid float for %s=%r; using default %s", name, raw, default)
        return default
    if minimum is not None and val < minimum:
        logger.warning("%s=%s below minimum %s; clamping", name, val, minimum)
        return minimum
    if maximum is not None and val > maximum:
        logger.warning("%s=%s above maximum %s; clamping", name, val, maximum)
        return maximum
    return val
